import logging
import importlib
import traceback

from ute_common_config.config import Config

from .exception import ConfigVariableDoesNotExist, CannotImportConfig, ConfigNotValid


class ErrorMessage(object):
    """A class to create error messages needed by this module."""

    @staticmethod
    def import_error(full_config_path, e):
        """Creates user-friendly information about an import error.

        :param string full_config_path: String representing the import path that failed.
        :param e: Captured exception.

        :return: Import error message.
        :rtype: string
        """
        return ("\n\n---------------------------------- IMPORT ERROR ------------------------------\n"
                "Provided configuration cannot be imported\n"
                "Configuration path: {}\n\n"
                "+++ Error message +++\n{}\n\n"
                "+++ Traceback +++\n{}"
                "------------------------------------------------------------------------------\n"
                "".format(full_config_path, e, traceback.format_exc()))

    @staticmethod
    def assert_error():
        """Creates user-friendly information that the CONFIGURATION global variable is required and the test cannot start without it.

        :return: Incorrect execution error message.
        :rtype: string
        """
        return ("\n\n--------------------------- INCORRECT EXECUTION ------------------------------\n"
                "It is not possible to find the CONFIGURATION variable. \n"
                "To solve this issue please add --variable to pybot execution command, e.g.:\n"
                "pybot --variable CONFIGURATION:Wroclaw.IAV_WRO_TL101 path/to/test\n"
                "------------------------------------------------------------------------------\n")

    @staticmethod
    def configuration_error():
        """Creates user-friendly information if case of configuration errors.

        :return: Configuration error message.
        :rtype: string
        """
        return ("\n\n--------------------------- CONFIGURATION HAS ERRORS -------------------------\n"
                "Please check the prints above to see where the testline configuration has errors\n"
                "------------------------------------------------------------------------------\n")


class Loader(object):
    """A class responsible for loading and validating the provided configuration package/module."""

    def __init__(self):
        self.log = logging.getLogger(__name__)

    def load_config_module(self, configuration, module_name='config'):
        """Load module/package which contains the testline configuration.

        :param string configuration:  Path to testline configuration without first package name e.g. config directory.
        :param string module_name:    Name of the first module used by the container for testline configurations.

        :raise: CannotImportConfig if the import operation failed.
        :raise: ConfigVariableNotExist if pybot was executed without the CONFIGURATION variable.

        :return: Loaded module.
        :rtype: module
        """
        if configuration is not None:
            try:
                return importlib.import_module('{}.{}'.format(module_name, configuration))
            except ImportError as e:
                self.log.error(ErrorMessage.import_error('{}.{}'.format(module_name, configuration), e))
                raise CannotImportConfig("It is not possible to import provided config.")
        else:
            self.log.error(ErrorMessage.assert_error())
            raise ConfigVariableDoesNotExist("Required Robot Framework variable not exist.")

    def validate_config_module(self, config_module):
        """Check if all configuration objects are valid.

        :param module config_module: Loaded module.

        :raise: ConfigNotValid if at least one configuration object is not valid.
        """
        attr_names = [i for i in dir(config_module) if self._should_be_checked(i)]
        if self._validate_object(config_module, attr_names):
            self.log.error(ErrorMessage.configuration_error())
            raise ConfigNotValid("Errors found in testline configuration.")

    def import_tl_config(self, config_module):
        """Import the tl object from module if it exists.

        :param module config_module: Loaded module.

        :return: Same module if the tl object doesn't exist or the tl object if it exist.
        """
        if self._hasattr(config_module, 'tl'):
            return config_module.tl
        return config_module

    def _should_be_checked(self, attr_name):
        blacklist = ["configschema", "ute_testline_configuration", "ta_testline_configuration"]
        if attr_name.startswith("_"):
            return False
        if attr_name in blacklist:
            return False
        return True

    def _validate_object(self, module, attr_names):
        is_error = False
        for attr_name in attr_names:
            m = getattr(module, attr_name)
            if isinstance(m, Config):
                msg = m.dump([module.__name__, attr_name])
                if msg:
                    self.log.error("{}\n".format(msg))
                    is_error = True
        return is_error

    def _hasattr(self, module, attr):
        try:
            return hasattr(module, attr)
        except KeyError:
            return False
